import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.taxZones().listTaxZones(Map.of("limit", 2));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("tax_zones")) {
    Map<?, ?> taxZone = (Map<?, ?>) row;
    System.out.println(taxZone.get("id") + " " + taxZone.get("name"));
}
Map<?, ?> pagination = (Map<?, ?>) body.get("pagination");
System.out.println(pagination.get("total") + " " + pagination.get("has_next"));

